parameters.jsCode:
// Join the AI's chosen products to the catalog to attach real list prices.
// The model only returns productId + quantity; prices are authoritative here.
const catalog = $('Aggregate Catalog Data').first().json.catalog || [];
const byId = new Map(catalog.map(p => [p.id, p]));

const ai = $json.output || $json;            // agent output parser nests under `output`
const wanted = Array.isArray(ai.items) ? ai.items : [];

const items = [];
const unmatched = [];   // productId the AI returned that isn't in the catalog
const unpriced = [];    // matched but no usable price -> never post a $0 line silently
for (const w of wanted) {
  const p = byId.get(w.productId);
  if (!p) { unmatched.push(w.productId); continue; }
  // listPrice is a MySQL decimal -> comes back as a STRING (e.g. "1000.00")
  const price = Number(p.listPrice);
  if (!Number.isFinite(price) || price <= 0) { unpriced.push(p.name || p.id); continue; }
  const qty = Number(w.quantity) > 0 ? Number(w.quantity) : 1;
  items.push({
    productId: p.id,
    productName: p.name,
    productSku: p.sku,
    unitPrice: price,
    billingFrequency: p.billingFrequency || 'one-time',
    quantity: qty,
  });
}

const total = items.reduce((s, i) => s + i.unitPrice * i.quantity, 0);

// pretty money for Slack, e.g. "$80,250.00" — falls back if the currency code is odd
const currency = ($('Set Default Quote Parameters').first().json.currency) || 'USD';
let totalFormatted;
try { totalFormatted = total.toLocaleString('en-US', { style: 'currency', currency }); }
catch (e) { totalFormatted = currency + ' ' + total.toFixed(2); }

return [{ json: {
  customerName: (ai.customerName || '').trim(),
  items,
  unmatched,
  unpriced,
  itemCount: items.length,
  total,
  totalFormatted,
} }];

